const F=require('./v266-scenarios.cjs'),G=require('./v267-scenarios.cjs');
function cases(networks,config,meta){const mr=F.scenario('מצפה רמון',7,{VICTORY_NEW_SOURCE:[7,14930],SHUFERSAL:[6,10000],RAMI_LEVY:[5,10000],YAYNO_BITAN_AND_CARREFOUR:[5,10000],TIV_TAAM:[4,10000],HAZI_HINAM:[4,10000],YOHANANOF:[7,1000]},'pickup',networks,config,meta),ta=G.telAviv(networks,config,meta),nt=F.scenario('נתניה',6,{SHUFERSAL:[6,30000],RAMI_LEVY:[6,27000],YAYNO_BITAN_AND_CARREFOUR:[6,10000],VICTORY_NEW_SOURCE:[5,25000],TIV_TAAM:[4,31000],HAZI_HINAM:[4,10000],YOHANANOF:[6,1000]},'pickup',networks,config,meta);const old=nt.cart.map(i=>i.barcode);nt.cart=nt.cart.map((i,j)=>({...i,barcode:G.natanyaCodes[j]}));nt.records=new Map(old.map((c,j)=>[G.natanyaCodes[j],nt.records.get(c)]));return [mr,ta,nt];}
function numeric(model,N){return {rows:model.rows.map(r=>Object.fromEntries(['chain','coverage','itemsTotal','fee','customerFee','total','minimumOrder','belowMinimum','deficit','full','qualifies','comparable','saving','savingPercent','winner','compareAmount','canOrder','rankAmount','basis'].map(k=>[k,r[k]??null]))),order:N.sortRows(model.relevant).map(r=>r.chain),winner:model.winner??null};}
module.exports={cases,numeric};
